// External Dependencies.
import React, { ReactElement } from 'react';

// Divi Dependencies.
import {
  ModuleContainer,
} from '@divi/module';

import {
  getAttrByMode,
} from '@divi/module-utils';

// Local Dependencies.
import { SectionFooterGroupModuleEditProps } from './types.ts';
import { ModuleStyles } from './styles.jsx';
import { moduleClassnames } from './module-classnames.js';
import { ModuleScriptData } from './module-script-data.jsx';

/**
 * Divi 5 Module edit component of visual builder.
 *
 * @since ??
 *
 * @param {SectionFooterGroupModuleEditProps} props React component props.
 *
 * @returns {ReactElement}
 */
const ModuleEdit = (props) => {
  const {
    attrs,
    id,
    name,
    elements,
    parentAttrs
  } = props;

  console.log( attrs )
  let {
    size: TitleSize
  } = getAttrByMode(attrs?.title?.advanced);

  // let title = getAttrByMode(attrs?.title?.innerContent);
  // let image = getAttrByMode(attrs?.image?.innerContent);
  // let link = getAttrByMode(attrs?.link?.innerContent);
  
  return (
    <ModuleContainer
      attrs={attrs}
      parentAttrs={parentAttrs}
      elements={elements}
      id={id}
      name={name}
      stylesComponent={ModuleStyles}
      classnamesFunction={moduleClassnames}
      scriptDataComponent={ModuleScriptData}
    >
      {
        elements.styleComponents({
          attrName: 'module',
        })
      }
      {
        elements.render({
          attrName: 'title',
          tagName: TitleSize
        })
      }
      
    </ModuleContainer>
  );
}

export {
  ModuleEdit,
};
